import mongoose from 'mongoose';

const childSchema = new mongoose.Schema(
  {
    // The id generated by the app, so local and cloud records match.
    _id: { type: String, required: true },
    therapistId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true, index: true },
    name: { type: String, required: true, trim: true, minlength: 1, maxlength: 100 },
    age: { type: Number, required: true, min: 4, max: 17 },
    focus: { type: String, required: true },
    plan: { type: mongoose.Schema.Types.Mixed, default: {} },
    parentIds: [{ type: mongoose.Schema.Types.ObjectId, ref: 'User' }],
  },
  { timestamps: true },
);

childSchema.index({ parentIds: 1 });

childSchema.methods.toPublic = function toPublic() {
  return { id: this._id, name: this.name, age: this.age, focus: this.focus, plan: this.plan };
};

export const Child = mongoose.model('Child', childSchema);
